 901	\begin{definition}[Formalization support: retained nondegenerate mass]
 902		\label{def:nondegenerate-line-pasting-mass}
 903		\lean{MIPStarRE.QPBT.nondegenerateLinePastingMass}
 904		\leanok
 905		\uses{def:line-point-dist}
 906		Fix low-degree parameters $L=(q,m,d,k)$, and write
 907		$D_{\mathsf{Line}}^L$ for the line-point distribution of
 908		Definition~\ref{def:line-point-dist}. For two independent samples
 909		$(\ell_1,x),(\ell_2,z)\sim D_{\mathsf{Line}}^L$, define the retained mass
 910		\[
 911			\mu_{\mathrm{nd}}(L)
 912			:= \sum_{\substack{(\ell_1,x),(\ell_2,z)\\
 913				\operatorname{dir}(\ell_1)\ne 0}}
 914			D_{\mathsf{Line}}^L(\ell_1,x)D_{\mathsf{Line}}^L(\ell_2,z).
 915		\]
 916		Thus $\mu_{\mathrm{nd}}(L)$ is the probability that the first sampled line
 917		has nonzero direction; the second line-point sample is unrestricted. This is
 918		a formalization-only quantity for the conditioning step in the proof of
 919		Lemma~\ref{lem:qld-xz-lines}. It does not replace the independent,
 920		unconditioned product law in that lemma's statement.
 921	\end{definition}
